import { SAMPLE_ACCOUNTANT } from './accountant-chapters';
import { SAMPLE_SHOP } from './shop-chapters';
import { SAMPLE_SIDE_HUSTLE } from './side-hustle-chapters';
import { SAMPLE_STUDENT } from './student-chapters';

/**
 * The four sample reports (Owner's groups), each generated by the Graylum positioning Skill for a fictional person
 * (docs/launch/design/landing/sample-personas.md): per chapter, what it gives that person and its key conclusion, and
 * the whole report, loaded only when a visitor opens it (the texts are long).
 */
export type SampleChapter = { give: string; key: string };
/** The 10-second card: who, what content for whom, how it earns, this week's first step (and the coach's warning). */
export type SampleSummary = { who: string; truth?: string; what: string; money: string; first: string };
export type SampleData = { generatedAt: string; summary: SampleSummary; chapters: readonly SampleChapter[] };

export const SAMPLE_CHAPTERS: Record<string, SampleData> = {
  accountant: SAMPLE_ACCOUNTANT,
  shop: SAMPLE_SHOP,
  'side-hustle': SAMPLE_SIDE_HUSTLE,
  student: SAMPLE_STUDENT,
};

const LOADERS: Record<string, () => Promise<{ default: { markdown: string } }>> = {
  accountant: () => import('./accountant.json'),
  shop: () => import('./shop.json'),
  'side-hustle': () => import('./side-hustle.json'),
  student: () => import('./student.json'),
};

/** The whole report as Markdown (sanitized: no @handles, no links, benchmarks as 对标账号 A/B/C). */
export async function loadSampleReport(slug: string): Promise<string> {
  const load = LOADERS[slug];
  return load ? (await load()).default.markdown : '';
}
